/**
 * Builds the receipt logo from public/logo.png into src/lib/receipt-logo.ts:
 * a 1-bit bitmap for the thermal printer (ESC/POS raster) and the same pixels
 * as a PNG data URI for the on-screen preview / browser print — so the preview
 * matches the paper, and the logo prints offline with no image request.
 *
 *   pnpm --filter web receipt-logo
 *
 * Run again after changing public/logo.png and commit the generated file.
 *
 * POS80 rule (paper tests, Nov 2026): a GS v 0 image whose data STARTS with
 * blank rows prints its data as lines of garbage text. This script crops the
 * blank rows and refuses to write a bitmap that would start blank.
 */
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { writeFileSync } from "node:fs";

const require = createRequire(import.meta.url);
// sharp ships with Next (image optimisation); borrow that copy.
// (not a direct dependency, so no types — this script uses only a few calls)
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const sharp: any = require(
  require.resolve("sharp", { paths: [dirname(require.resolve("next/package.json"))] }),
);

const ROOT = join(dirname(new URL(import.meta.url).pathname), "..");
const SRC = join(ROOT, "public/logo.png");
const OUT = join(ROOT, "src/lib/receipt-logo.ts");

/** 208 dots = 26 mm on a 203 dpi head; a multiple of 8. This size printed cleanly on the POS80. */
const SIZE = 208;
/** Red disc + dark shadow → black; cream letters + yellow bite → white. */
const THRESHOLD = 150;
/** Most leading 0x00 bytes seen in a GS v 0 that printed correctly was 35; failures had 367+. */
const MAX_LEADING_BLANK_BYTES = 32;

async function main() {
  const mono = sharp(SRC)
    .flatten({ background: "#ffffff" })
    .resize(SIZE, SIZE)
    .greyscale()
    .threshold(THRESHOLD);

  const { data, info } = await mono.clone().raw().toBuffer({ resolveWithObject: true });
  const { width, channels } = info;
  const bytesPerRow = width / 8;
  const rows: Buffer[] = [];
  for (let y = 0; y < info.height; y++) {
    const row = Buffer.alloc(bytesPerRow);
    for (let x = 0; x < width; x++) {
      if (data[(y * width + x) * channels] < 128) row[x >> 3] |= 0x80 >> (x & 7);
    }
    rows.push(row);
  }

  // Crop blank rows top and bottom (the printer must never start on a blank row).
  const inked = (r: Buffer) => r.some((b) => b !== 0);
  const top = rows.findIndex(inked);
  const bottom = rows.length - [...rows].reverse().findIndex(inked);
  const kept = rows.slice(top, bottom);
  const bits = Buffer.concat(kept);
  const height = kept.length;

  const leading = bits.findIndex((b) => b !== 0);
  if (width % 8 !== 0) throw new Error(`width ${width} is not a multiple of 8`);
  if (height < 1 || height > 255) throw new Error(`height ${height} must be 1..255 (one GS v 0 command)`);
  if (leading < 0 || leading > MAX_LEADING_BLANK_BYTES) {
    throw new Error(`bitmap starts with ${leading} blank bytes (max ${MAX_LEADING_BLANK_BYTES}) — POS80 would print garbage`);
  }

  const png = await sharp(SRC)
    .flatten({ background: "#ffffff" })
    .resize(SIZE, SIZE)
    .greyscale()
    .threshold(THRESHOLD)
    .extract({ left: 0, top, width, height })
    .png({ palette: true, colours: 2 })
    .toBuffer();

  writeFileSync(
    OUT,
    `// Generated by scripts/build-receipt-logo.ts from public/logo.png — do not edit.
// Rebuild: pnpm --filter web receipt-logo

/** Receipt header logo: ${width}×${height} dots (${width / 8} mm wide at 203 dpi). */
export const RECEIPT_LOGO = {
  width: ${width},
  height: ${height},
  /** 1 bit per dot, rows top to bottom, MSB = leftmost, 1 = black (ESC/POS GS v 0). Row 0 has ink. */
  bitsBase64: "${bits.toString("base64")}",
  /** Same pixels for the HTML receipt. */
  pngDataUri: "data:image/png;base64,${png.toString("base64")}",
} as const;
`,
  );
  console.log(
    `Wrote ${OUT} (${width}×${height}, raster ${bits.length} B, leading blank bytes ${leading}, png ${png.length} B)`,
  );
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
